cat > scripts/corpus-run.ts <<'EOF'
export type CorpusCandidate = { repo: string; score: number };
export type CorpusResult = { done: string[]; failed: { repo: string; reason: string }[] };

export async function runCorpus(opts: {
  candidates: CorpusCandidate[];
  top: number;
  review: (repo: string) => Promise<unknown>;
  write: (path: string, data: unknown) => Promise<void>;
}): Promise<CorpusResult> {
  const picked = [...opts.candidates]
    .sort((a, b) => b.score - a.score || (a.repo < b.repo ? -1 : a.repo > b.repo ? 1 : 0))
    .slice(0, Math.max(0, opts.top));
  const done: string[] = [];
  const failed: { repo: string; reason: string }[] = [];
  for (const { repo } of picked) {
    try {
      const data = await opts.review(repo);
      await opts.write(`reports/corpus/${repo.replace("/", "__")}/review.json`, data);
      done.push(repo);
    } catch (e) {
      failed.push({ repo, reason: e instanceof Error ? e.message : String(e) });
    }
  }
  await opts.write("reports/corpus/index.json", { done, failed });
  return { done, failed };
}
EOF
cat > tests/corpus-run.test.ts <<'EOF'
import { expect, test } from "bun:test";
import { runCorpus } from "../scripts/corpus-run";

test("top by score, ties by name, continues past failures", async () => {
  const writes: Record<string, unknown> = {};
  const seen: string[] = [];
  const res = await runCorpus({
    candidates: [
      { repo: "b/y", score: 5 },
      { repo: "a/x", score: 5 },
      { repo: "c/z", score: 9 },
      { repo: "d/w", score: 1 },
    ],
    top: 3,
    review: async (r) => {
      seen.push(r);
      if (r === "a/x") throw new Error("boom");
      return { r };
    },
    write: async (p, d) => {
      writes[p] = d;
    },
  });
  expect(seen).toEqual(["c/z", "a/x", "b/y"]);
  expect(res).toEqual({ done: ["c/z", "b/y"], failed: [{ repo: "a/x", reason: "boom" }] });
  expect(Object.keys(writes).sort()).toEqual([
    "reports/corpus/b__y/review.json",
    "reports/corpus/c__z/review.json",
    "reports/corpus/index.json",
  ]);
  expect(writes["reports/corpus/index.json"]).toEqual(res);
});
EOF
bun test tests/corpus-run.test.ts 2>&1 | tail -6; bun run typecheck 2>&1 | tail -3; bun test 2>&1 | tail -4

